{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Rapamycin, the closest high-similarity analogue, was measured at high levels in mouse brain after intraperitoneal administration, directly demonstrating that this macrocyclic pipecolate class can achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Preclinical studies in several species show rapamycin crosses the blood-brain barrier, measured by CSF and brain tissue levels or brain mTORC1 inhibition, supporting transfer of CNS access to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Rapamycin was detected in human brain tumor tissue after daily systemic administration, confirming meaningful human CNS exposure for the closest analogue class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Temsirolimus, a more polar rapamycin prodrug, showed CSF detection in only one of nine patients, indicating that adding polar ester groups can impair CNS penetration; the query lacks this polar ester modification.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "One rapamycin study reported poor BBB traversal and no brain recombination, indicating that efflux or limited uptake can occur in this class; however, this is outweighed by direct positive measurements.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a rapamycin/FK506-class macrocyclic pipecolate. The closest high-similarity evidence (rapamycin) shows direct brain and CSF penetration in animals and humans, while the negative temsirolimus record reflects a polar prodrug modification absent in the query. Overall, meaningful CNS access is supported.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the exact query molecule",
    "P-glycoprotein/BCRP efflux status of the query not directly measured",
    "Human CNS exposure data for the query are unavailable"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

